def keep_the_last_of_each_timestamp(apps, schema_editor):
    """Entered samples sharing an instance and a timestamp: the last one
    written stays, as the per-second constraint added below and
    CustomMetricSample.record() decide from now on. Existing timestamps keep
    their fraction of a second."""
    Sample = apps.get_model("metrology", "CustomMetricSample")
    entered = Sample.objects.exclude(source="derived")
    shared = list(
        entered.values("metric_instance_id", "timestamp")
        .annotate(count=Count("id"))
        .filter(count__gt=1)
        .order_by()
    )
    for row in shared:
        ids = list(
            entered.filter(
                metric_instance_id=row["metric_instance_id"],
                timestamp=row["timestamp"],
            )
            .order_by("-created_at", "-id")
            .values_list("id", flat=True)
        )
        Sample.objects.filter(id__in=ids[1:]).delete()


def rename_frequency(old, new):
    def forwards(apps, schema_editor):
        """Same period, same staleness threshold: only the name changes, so
        nothing is marked for recomputation."""
        MetricInstance = apps.get_model("metrology", "MetricInstance")
        MetricInstance.objects.filter(collection_frequency=old).update(
            collection_frequency=new
        )

    return forwards


